
(function(root){'use strict';const reviewed={"27.1": [["Använd vec(F) = q[vec(v) × vec(B)] med i × j = k, j × k = i och k × i = j.", "(a) B = 1,40 i T ger vec(v) × vec(B) = −v_yB k = 5,39·10⁴ k.", "Den negativa laddningen ger vec(F) = −6,68·10⁻⁴ k N.", "(b) B = 1,40 k T ger vec(v) × vec(B) = v_yB i−v_xB j = (−5,39 i−5,87 j)·10⁴.", "Multiplikation med q ger vec(F) = (6,68 i+7,27 j)·10⁻⁴ N."], ["Use vec(F) = q[vec(v) × vec(B)] with i × j = k, j × k = i and k × i = j.", "(a) B = 1.40 i T gives vec(v) × vec(B) = −v_yB k = 5.39×10⁴ k.", "The negative charge gives vec(F) = −6.68×10⁻⁴ k N.", "(b) B = 1.40 k T gives vec(v) × vec(B) = v_yB i−v_xB j = (−5.39 i−5.87 j)×10⁴.", "Multiplying by q gives vec(F) = (6.68 i+7.27 j)×10⁻⁴ N."]], "27.2": [["Magnetkraften måste balansera tyngden mg för att rörelsen ska förbli vågrät.", "Minsta fält för given fart fås när fältet är vinkelrätt mot hastigheten, så |q|vB = mg.", "Massan är 0,190 g = 1,90·10⁻⁴ kg och B = mg/(|q|v) ≈ 1,45 T.", "Välj öster = +x, norr = +y och upp = +z.", "Norr kors öster pekar nedåt för positiv laddning; den negativa laddningen vänder kraften uppåt. Fältet pekar österut."], ["Magnetic force must balance weight mg to maintain horizontal motion.", "For a given speed the smallest field is perpendicular to velocity, so |q|vB = mg.", "Mass is 0.190 g = 1.90×10⁻⁴ kg and B = mg/(|q|v) ≈ 1.45 T.", "Choose east = +x, north = +y and up = +z.", "North crossed with east points down for positive charge; the negative charge reverses force upward. The field points east."]], "27.3": [["(a) Välj öster = +x, norr = +y och upp = +z.", "För positiv laddning är norr kors upp = öster, vilket stämmer med avböjningen.", "Laddningen är alltså positiv.", "(b) Hastighet och fält är vinkelräta: F = qvB.", "F = (9,00·10⁻⁶ C)(4,78·10³ m/s)(1,27 T) = 0,0546 N österut."], ["(a) Choose east = +x, north = +y and up = +z.", "For positive charge north crossed with up is east, matching the deflection.", "The charge is therefore positive.", "(b) Velocity and field are perpendicular: F = qvB.", "F = (9.00×10⁻⁶ C)(4.78×10³ m/s)(1.27 T) = 0.0546 N eastward."]], "27.4": [["Kraften är q(vec(v) × vec(B)).", "Fältkomponenten 0,980 j är parallell med hastigheten och ger ingen kraft.", "Eftersom j × i = −k är vec(F) = −q(3,00·10⁴)(1,63) k = −5,97·10⁻⁴ k N.", "Dividera med massan: vec(a) = −(5,97·10⁻⁴)/(1,81·10⁻³) k.", "Accelerationen har beloppet 0,330 m/s² mot −z."], ["Force is q(vec(v) × vec(B)).", "The field component 0.980 j is parallel to velocity and contributes no force.", "Since j × i = −k, vec(F) = −q(3.00×10⁴)(1.63) k = −5.97×10⁻⁴ k N.", "Divide by mass: vec(a) = −(5.97×10⁻⁴)/(1.81×10⁻³) k.", "Acceleration magnitude is 0.330 m/s² toward −z."]], "27.5": [["Elektronen har q = −e, så kraften är motsatt vec(v) × vec(B).", "Fältet är +z och kraften −y.", "Hastigheten måste då vara längs −x: (−i) × k = +j och negativ laddning vänder kraften till −j.", "Farten är v = F/(eB) = (5,50·10⁻¹⁸)/[(1,602·10⁻¹⁹)(0,200)] ≈ 172 m/s.", "Alltså vec(v) = −172 i m/s i xy-planet."], ["The electron has q = −e, so its force is opposite vec(v) × vec(B).", "The field is +z and the force −y.", "Velocity must therefore be along −x: (−i) × k = +j and the negative charge reverses force to −j.", "Speed is v = F/(eB) = (5.50×10⁻¹⁸)/[(1.602×10⁻¹⁹)(0.200)] ≈ 172 m/s.", "Thus vec(v) = −172 i m/s in the xy plane."]], "27.6": [["Magnetkraftens belopp är evB|sinθ|, så a = evB|sinθ|/m_e.", "(a) Vid θ = 90° är accelerationen maximal.", "a_max = (1,602·10⁻¹⁹)(2,10·10⁶)(0,0760)/(9,109·10⁻³¹) ≈ 2,81·10¹⁶ m/s².", "Parallella eller antiparallella riktningar ger a_min = 0.", "(b) En fjärdedel av maximum kräver sinθ = 0,25, vilket ger θ ≈ 14,5° eller 165,5° mellan 0° och 180°."], ["Magnetic force magnitude is evB|sinθ|, so a = evB|sinθ|/m_e.", "(a) At θ = 90° acceleration is maximal.", "a_max = (1.602×10⁻¹⁹)(2.10×10⁶)(0.0760)/(9.109×10⁻³¹) ≈ 2.81×10¹⁶ m/s².", "Parallel or antiparallel directions give a_min = 0.", "(b) One-quarter of maximum requires sinθ = 0.25, giving θ ≈ 14.5° or 165.5° between 0° and 180°."]], "27.7": [["(a) För protonen längs +x är F_y = −ev_pB_z och F_z = ev_pB_y.", "Den angivna kraften har ingen z-komponent, så B_y = 0 och B_z = −2,06·10⁻¹⁶/(e·1500) ≈ −0,857 T.", "För elektronen längs −z är F_y = ev_eB_x, vilket ger B_x ≈ 1,18 T.", "Fältet är (1,18 i−0,857 k) T, med belopp 1,46 T vid 36,1° från +x mot −z.", "(b) För elektronen längs −y ger q(vec(v) × vec(B)) = (−4,94 i−6,79 k)·10⁻¹⁶ N, med belopp 8,40·10⁻¹⁶ N."], ["(a) For the proton along +x, F_y = −ev_pB_z and F_z = ev_pB_y.", "The stated force has no z component, so B_y = 0 and B_z = −2.06×10⁻¹⁶/(e·1500) ≈ −0.857 T.", "For the electron along −z, F_y = ev_eB_x, giving B_x ≈ 1.18 T.", "The field is (1.18 i−0.857 k) T, magnitude 1.46 T at 36.1° from +x toward −z.", "(b) For the electron along −y, q(vec(v) × vec(B)) = (−4.94 i−6.79 k)×10⁻¹⁶ N, magnitude 8.40×10⁻¹⁶ N."]], "27.8": [["För q = −5,90 nC och vec(B) = −1,30 k T är F_x = |q|Bv_y och F_y = −|q|Bv_x.", "(a) v_x = −F_y/(|q|B) ≈ −99,1 m/s.", "v_y = F_x/(|q|B) ≈ −52,2 m/s.", "(b) v_z kan inte bestämmas eftersom den inte bidrar till kryssprodukten.", "(c) vec(v) · vec(F) = 0 eftersom magnetkraften alltid är vinkelrät mot hastigheten. Vinkeln är 90° för dessa icke-nollvektorer."], ["For q = −5.90 nC and vec(B) = −1.30 k T, F_x = |q|Bv_y and F_y = −|q|Bv_x.", "(a) v_x = −F_y/(|q|B) ≈ −99.1 m/s.", "v_y = F_x/(|q|B) ≈ −52.2 m/s.", "(b) v_z cannot be determined because it contributes zero to the cross product.", "(c) vec(v) · vec(F) = 0 because magnetic force is always perpendicular to velocity. The angle is 90° for these nonzero vectors."]], "27.9": [["Arean är A = π(0,0610 m)² ≈ 0,01169 m².", "Flödesbeloppet är |Φ| = BA|cosθ|, där θ mäts från ytans normal.", "(a) Normalen är +z, så θ = 0° och |Φ| ≈ 2,69·10⁻³ Wb.", "(b) Vid θ = 53,1° är |Φ| = 0,230·0,01169·cos53,1° ≈ 1,61·10⁻³ Wb.", "(c) Fältet längs +y ligger i planet, så normalkomponenten och flödet är noll."], ["Area is A = π(0.0610 m)² ≈ 0.01169 m².", "Flux magnitude is |Φ| = BA|cosθ|, where θ is measured from the surface normal.", "(a) The normal is +z, so θ = 0° and |Φ| ≈ 2.69×10⁻³ Wb.", "(b) At θ = 53.1°, |Φ| = 0.230·0.01169·cos53.1° ≈ 1.61×10⁻³ Wb.", "(c) The field along +y lies in the plane, so its normal component and flux vanish."]], "27.10": [["Kvadratens area är A = (0,0420 m)² = 0,001764 m².", "En normal till xy-planet är ±k.", "Endast fältets z-komponent bidrar till flödet.", "Flödesbeloppet är |Φ| = |B_z|A = 0,450·0,001764 ≈ 7,94·10⁻⁴ Wb.", "Det orienterade flödets tecken beror på vald normal."], ["Square area is A = (0.0420 m)² = 0.001764 m².", "A normal to the xy plane is ±k.", "Only the field’s z component contributes to flux.", "Flux magnitude is |Φ| = |B_z|A = 0.450·0.001764 ≈ 7.94×10⁻⁴ Wb.", "The oriented flux sign depends on the selected normal."]]};for(const e of root.EmberChapter27DraftExercises){const v=reviewed[e.id];if(v){e.sv.steps=v[0];e.en.steps=v[1]}}})(window);

(function(root){'use strict';const reviewed={"27.11": [["Slut öppningen med en tänkt cirkelyta så att plasten och cirkeln tillsammans bildar en sluten yta.", "Gauss lag för magnetism ger Φ_plast+Φ_öppning = 0.", "Öppningens utåtriktade normal pekar uppåt och radien är 0,014 m.", "Därför Φ_öppning = (2,00 T)π(0,014 m)²cos24° ≈ +1,13·10⁻³ Wb.", "Flödet utåt genom plasten är Φ_plast ≈ −1,13·10⁻³ Wb; minustecknet anger ett nettoflöde inåt."], ["Close the opening with an imaginary circular surface so the plastic and circle together form a closed surface.", "Gauss’s law for magnetism gives Φ_plastic+Φ_opening = 0.", "The opening’s outward normal points upward and its radius is 0.014 m.", "Thus Φ_opening = (2.00 T)π(0.014 m)²cos24° ≈ +1.13×10⁻³ Wb.", "Outward flux through the plastic is Φ_plastic ≈ −1.13×10⁻³ Wb; the negative sign means net inward flux."]], "27.12": [["Arean är A = 0,0290·0,0300 = 8,70·10⁻⁴ m².", "Fältet ligger 27,5° över planet, så normalkomponenten är B sin27,5°.", "Flödesbeloppet är Φ = AB sin27,5°.", "Lös B = (4,50·10⁻⁴)/[(8,70·10⁻⁴)sin27,5°].", "Fältstyrkan är cirka 1,12 T."], ["Area is A = 0.0290·0.0300 = 8.70×10⁻⁴ m².", "The field is 27.5° above the plane, so its normal component is B sin27.5°.", "Flux magnitude is Φ = AB sin27.5°.", "Solve B = (4.50×10⁻⁴)/[(8.70×10⁻⁴)sin27.5°].", "The field magnitude is about 1.12 T."]], "27.13": [["(a) Ytan abcd ligger i yz-planet, så dess utåtnormal ligger längs x och flödet från B längs z är noll.", "(b) Ytan befc ligger i xy-planet med utåtnormal −z och area 0,300·0,300 = 0,0900 m².", "Dess flöde är −0,128·0,0900 = −0,01152 Wb.", "(c) Den lutande ytan aefd har samma projicerade area i xy-planet och positiv z-komponent av utåtnormalen. Dess flöde är +0,01152 Wb.", "(d) Triangeländarnas normaler ligger längs ±y och ger noll. Summan över alla fem ytor är noll enligt Gauss lag för magnetism."], ["(a) Surface abcd lies in the yz plane, so its outward normal is along x and flux from B along z is zero.", "(b) Surface befc lies in the xy plane with outward normal −z and area 0.300·0.300 = 0.0900 m².", "Its flux is −0.128·0.0900 = −0.01152 Wb.", "(c) Inclined surface aefd has the same projected area in the xy plane and a positive z component of its outward normal. Its flux is +0.01152 Wb.", "(d) The triangular end normals are along ±y and give zero. The sum over all five surfaces is zero by Gauss’s law for magnetism."]], "27.14": [["Diametern är 10,0 cm, så r = 0,0500 m.", "Magnetkraften ger centripetalkraften evB = m_ev²/r.", "(a) B = m_ev/(er) ≈ 1,60·10⁻⁴ T. Vid A måste kraften peka åt höger; för en negativ elektron måste fältet peka in i sidan.", "(b) Halvcirkelns längd är πr och magnetkraften ändrar inte farten.", "Därmed t = πr/v ≈ 1,11·10⁻⁷ s."], ["The diameter is 10.0 cm, so r = 0.0500 m.", "Magnetic force provides centripetal force evB = m_ev²/r.", "(a) B = m_ev/(er) ≈ 1.60×10⁻⁴ T. At A the force must point right; for a negative electron the field must point into the page.", "(b) The semicircle length is πr and magnetic force does not change speed.", "Thus t = πr/v ≈ 1.11×10⁻⁷ s."]], "27.15": [["Samma bana har radien r = 0,0500 m.", "Centripetalvillkoret för protonen ger B = m_pv/(er) ≈ 0,294 T.", "Kraften vid A måste peka åt höger.", "Eftersom protonen är positiv måste B peka ut ur sidan, motsatt elektronfallet.", "Halvcirkelns längd och farten är samma som i 27.14, så t = πr/v ≈ 1,11·10⁻⁷ s."], ["The same path has radius r = 0.0500 m.", "The centripetal condition for the proton gives B = m_pv/(er) ≈ 0.294 T.", "Force at A must point right.", "Since the proton is positive, B must point out of the page, opposite the electron case.", "The semicircle length and speed match 27.14, so t = πr/v ≈ 1.11×10⁻⁷ s."]], "27.16": [["Alfapartikelns laddning är q = +2e och dess vinkelräta fart är 3,56·10⁴ m/s.", "(a) Ur qvB = mv²/r blir diametern d = 2mv/(qB) ≈ 8,20·10⁻⁴ m.", "(b) Farten är konstant.", "(c) Accelerationen är a = qvB/m ≈ 3,09·10¹² m/s², riktad inåt mot cirkelns centrum.", "(d) Kraften är alltid vinkelrät mot hastigheten, så effekten vec(F) · vec(v) är noll och rörelseenergin ändras inte i modellen."], ["The alpha-particle charge is q = +2e and its perpendicular speed is 3.56×10⁴ m/s.", "(a) From qvB = mv²/r, diameter d = 2mv/(qB) ≈ 8.20×10⁻⁴ m.", "(b) Speed is constant.", "(c) Acceleration is a = qvB/m ≈ 3.09×10¹² m/s², directed inward toward the circle center.", "(d) Force is always perpendicular to velocity, so power vec(F) · vec(v) is zero and kinetic energy does not change in the model."]], "27.17": [["Fritt fall från vila ger farten v = √(2gh) = √(2·9,80·125) ≈ 49,5 m/s nedåt.", "Laddningen är q = −(4,00·10⁸)e ≈ −6,41·10⁻¹¹ C.", "Hastighet och fält är vinkelräta, så |F| = |q|vB ≈ 7,93·10⁻¹⁰ N.", "Välj öster = +x, norr = +y och upp = +z. Nedåt kors väster är (−z) × (−x) = +y.", "Den negativa laddningen vänder kraften söderut."], ["Free fall from rest gives speed v = √(2gh) = √(2·9.80·125) ≈ 49.5 m/s downward.", "Charge is q = −(4.00×10⁸)e ≈ −6.41×10⁻¹¹ C.", "Velocity and field are perpendicular, so |F| = |q|vB ≈ 7.93×10⁻¹⁰ N.", "Choose east = +x, north = +y and up = +z. Down crossed with west is (−z) × (−x) = +y.", "The negative charge reverses the force southward."]], "27.18": [["Rörelseenergin är K = 5,0 MeV = 8,01·10⁻¹³ J.", "I den ickerelativistiska approximationen är K = m_pv²/2.", "(a) v = √(2K/m_p) ≈ 3,1·10⁷ m/s, cirka 0,10c. Approximationen är användbar men inte exakt.", "(b) Magnetkraften ger cirkelrörelse med r = m_pv/(eB).", "Radien är cirka 0,17 m. Den negativa jonladdningen ändrar banans riktning men inte dess radie."], ["Kinetic energy is K = 5.0 MeV = 8.01×10⁻¹³ J.", "In the nonrelativistic approximation K = m_pv²/2.", "(a) v = √(2K/m_p) ≈ 3.1×10⁷ m/s, about 0.10c. The approximation is useful but not exact.", "(b) Magnetic force produces circular motion with r = m_pv/(eB).", "The radius is about 0.17 m. Negative ion charge changes orbit direction but not its radius."]], "27.19": [["(a) Radien är 0,950/2 = 0,475 m. Ur |q|vB = mv²/r fås v = (3e)(0,250)(0,475)/(12m_p) ≈ 2,84·10⁶ m/s.", "Nedåt kors ut ur sidan pekar åt vänster för positiv laddning.", "Den observerade svängen åt höger kräver därför negativ laddning.", "(b) Kvoten |F_B|/(mg) = |q|vB/(mg) ≈ 1,7·10¹², så tyngden är försumbar för banan.", "(c) Magnetkraften är vinkelrät mot hastigheten och utför inget arbete; utan tyngdkraft är in- och utgångsfarten lika."], ["(a) Radius is 0.950/2 = 0.475 m. From |q|vB = mv²/r, v = (3e)(0.250)(0.475)/(12m_p) ≈ 2.84×10⁶ m/s.", "Down crossed with out of the page points left for positive charge.", "The observed turn right therefore requires negative charge.", "(b) The ratio |F_B|/(mg) = |q|vB/(mg) ≈ 1.7×10¹², so gravity is negligible for the trajectory.", "(c) Magnetic force is perpendicular to velocity and does no work; neglecting gravity, entry and exit speeds are equal."]], "27.20": [["(a) Centripetalvillkoret evB = mv²/r ger v = eBr/m ≈ 8,52·10⁵ m/s.", "(b) Tiden för ett halvt varv är t = πr/v.", "Ekvivalent är t = πm/(eB) ≈ 2,73·10⁻⁸ s.", "(c) Från vila ger energibevarande eV = mv²/2.", "Spänningens belopp är V = mv²/(2e) ≈ 7,57 kV."], ["(a) The centripetal condition evB = mv²/r gives v = eBr/m ≈ 8.52×10⁵ m/s.", "(b) Time for half a circle is t = πr/v.", "Equivalently t = πm/(eB) ≈ 2.73×10⁻⁸ s.", "(c) From rest energy conservation gives eV = mv²/2.", "Voltage magnitude is V = mv²/(2e) ≈ 7.57 kV."]]};for(const e of root.EmberChapter27DraftExercises){const v=reviewed[e.id];if(v){e.sv.steps=v[0];e.en.steps=v[1]}}})(window);

(function(root){'use strict';const reviewed={"27.21": [["Elektronen antas starta från vila och behandlas ickerelativistiskt.", "Accelerationsspänningen ger eV = m_ev²/2.", "Därmed v = √(2eV/m_e) ≈ 2,65·10⁷ m/s.", "Den tvärgående magnetkraften ger m_ev²/r = evB.", "Alltså B = m_ev/(er) ≈ 8,31·10⁻⁴ T."], ["Assume the electron starts from rest and use nonrelativistic energy.", "The accelerating voltage gives eV = m_ev²/2.", "Thus v = √(2eV/m_e) ≈ 2.65×10⁷ m/s.", "The transverse magnetic force provides m_ev²/r = evB.", "Therefore B = m_ev/(er) ≈ 8.31×10⁻⁴ T."]], "27.22": [["En riktningsändring på 90° motsvarar en kvarts cirkel.", "Båglängden s = 1,10 cm ger r = 2s/π ≈ 7,00·10⁻³ m.", "Centripetalvillkoret är evB = m_pv²/r.", "Lös B = m_pv/(er).", "Insättning ger B ≈ 1,79·10⁻³ T."], ["A 90° change of direction is a quarter circle.", "Arc length s = 1.10 cm gives r = 2s/π ≈ 7.00×10⁻³ m.", "The centripetal condition is evB = m_pv²/r.", "Solve B = m_pv/(er).", "Substitution gives B ≈ 1.79×10⁻³ T."]], "27.23": [["För icke-noll laddning och försumbar tyngd kräver oavböjd rörelse q[vec(E)+vec(v) × vec(B)] = 0.", "Alltså vec(E) = −vec(v) × vec(B).", "Här j × (−k) = −i, så vec(v) × vec(B) = −(5,85·10³)(1,35)i.", "Både (a) positiv och (b) negativ laddning kräver vec(E) = +7,90·10³ i V/m.", "Byte av laddningstecken vänder båda krafterna tillsammans, så balansfältet är detsamma."], ["For nonzero charge and negligible weight, undeflected motion requires q[vec(E)+vec(v) × vec(B)] = 0.", "Hence vec(E) = −vec(v) × vec(B).", "Here j × (−k) = −i, so vec(v) × vec(B) = −(5.85×10³)(1.35)i.", "Both (a) positive and (b) negative charge require vec(E) = +7.90×10³ i V/m.", "Reversing the charge reverses both forces together, so the balancing field is the same."]], "27.24": [["(a) Oavböjd passage kräver eE = evB, så v = E/B = 1,56·10⁴/(4,62·10⁻³) ≈ 3,38·10⁶ m/s.", "(b) En möjlig orientering är vec(v) längs +x, vec(B) längs +z och vec(E) längs +y.", "Då vec(E) = −vec(v) × vec(B), så de elektriska och magnetiska krafterna motverkar varandra även för elektronen.", "(c) Utan E blir radien r = m_ev/(eB) ≈ 4,16 mm.", "Perioden är T = 2πr/v = 2πm_e/(eB) ≈ 7,73 ns."], ["(a) Undeflected passage requires eE = evB, so v = E/B = 1.56×10⁴/(4.62×10⁻³) ≈ 3.38×10⁶ m/s.", "(b) One possible orientation is vec(v) along +x, vec(B) along +z and vec(E) along +y.", "Then vec(E) = −vec(v) × vec(B), so electric and magnetic forces oppose each other for the electron too.", "(c) Removing E gives radius r = m_ev/(eB) ≈ 4.16 mm.", "Period is T = 2πr/v = 2πm_e/(eB) ≈ 7.73 ns."]], "27.25": [["Alfapartikeln får energin qV_acc = mv²/2 vid accelerationen.", "Med q = 2e är v = √(2qV_acc/m) ≈ 4,17·10⁵ m/s.", "Plattfältet är E = V/d = 150/0,00850 ≈ 1,76·10⁴ V/m, uppåt från den positiva undre plattan.", "Oavböjd rörelse kräver qE = qvB, så B = E/v ≈ 0,0423 T.", "För positiv laddning måste magnetkraften peka nedåt; med hastighet åt höger pekar B ut ur sidan. Plattarean behövs inte i idealmodellen."], ["The alpha particle gains qV_acc = mv²/2 during acceleration.", "With q = 2e, v = √(2qV_acc/m) ≈ 4.17×10⁵ m/s.", "The plate field is E = V/d = 150/0.00850 ≈ 1.76×10⁴ V/m, upward from the positive lower plate.", "No deflection requires qE = qvB, so B = E/v ≈ 0.0423 T.", "For positive charge magnetic force must point down; with velocity rightward B points out of the page. Plate area is not needed in the ideal model."]], "27.26": [["(a) En hastighetsselektor uppfyller E = vB för oavböjda joner.", "E = (1,82·10⁶)(0,510) ≈ 9,28·10⁵ V/m.", "(b) Plattavståndet är 5,20 mm = 5,20·10⁻³ m.", "För homogent fält är spänningsbeloppet V = Ed.", "V ≈ (9,28·10⁵)(5,20·10⁻³) = 4,83 kV."], ["(a) A velocity selector satisfies E = vB for undeflected ions.", "E = (1.82×10⁶)(0.510) ≈ 9.28×10⁵ V/m.", "(b) Plate separation is 5.20 mm = 5.20×10⁻³ m.", "For a uniform field the voltage magnitude is V = Ed.", "V ≈ (9.28×10⁵)(5.20×10⁻³) = 4.83 kV."]], "27.27": [["(a) Selektorn ger v = E/B₁ = 160/0,0313 ≈ 5,11·10³ m/s.", "(b) Enkelt joniserade atomer har laddningsbelopp e.", "I det andra fältet gäller evB₂ = mv²/r.", "Lös m = eB₂r/v.", "Insättning ger m ≈ 9,43·10⁻²⁶ kg."], ["(a) The selector gives v = E/B₁ = 160/0.0313 ≈ 5.11×10³ m/s.", "(b) Singly ionized atoms have charge magnitude e.", "In the second field evB₂ = mv²/r.", "Solve m = eB₂r/v.", "Substitution gives m ≈ 9.43×10⁻²⁶ kg."]], "27.28": [["Vid samma fart, laddningsbelopp och magnetfält är r = mv/(|q|B), så r ∝ m.", "Radieskillnaden är Δr = r_C(m₁₅−m₁₄)/m_C.", "Insättning ger Δr = 0,125(2,49−2,32)/1,99 ≈ 0,0107 m.", "Båda jonerna följer halvcirklar till detektorn, så skillnaden i diametrar är 2Δr.", "Separationen är 0,0214 m = 2,14 cm."], ["At the same speed, charge magnitude and magnetic field, r = mv/(|q|B), so r ∝ m.", "The radius difference is Δr = r_C(m₁₅−m₁₄)/m_C.", "Substitution gives Δr = 0.125(2.49−2.32)/1.99 ≈ 0.0107 m.", "Both ions follow semicircles to the detector, so their diameter difference is 2Δr.", "Separation is 0.0214 m = 2.14 cm."]], "27.29": [["I homogent fält summeras krafterna på trådens segment till vec(F) = I[Δvec(r) × vec(B)].", "Förskjutningen i fältet är Δvec(r) = 0,600 i+0,300 j m.", "Med vec(B) = 0,240 k T, i × k = −j och j × k = i blir vec(F) = (0,324 i−0,648 j) N.", "Beloppet är √(0,324²+0,648²) ≈ 0,724 N.", "Vinkeln är arctan(0,648/0,324) ≈ 63,4° nedanför riktningen åt höger."], ["In a uniform field forces on the wire segments sum to vec(F) = I[Δvec(r) × vec(B)].", "Displacement inside the field is Δvec(r) = 0.600 i+0.300 j m.", "With vec(B) = 0.240 k T, i × k = −j and j × k = i, vec(F) = (0.324 i−0.648 j) N.", "Magnitude is √(0.324²+0.648²) ≈ 0.724 N.", "The angle is arctan(0.648/0.324) ≈ 63.4° below the rightward direction."]], "27.30": [["För vinkelrät ström är F = ILB = (1,5)(2,5)(55·10⁻⁶) ≈ 2,1·10⁻⁴ N.", "Välj öster = +x, norr = +y och upp = +z.", "(a) Öster kors norr = uppåt: kraften är 2,1·10⁻⁴ N uppåt.", "(b) Uppåt kors norr = väster: samma belopp verkar västerut.", "(c) Ström från norr till söder är antiparallell med fältet och F = 0. (d) Kraften är vanligtvis liten jämfört med vardagliga mekaniska krafter."], ["For perpendicular current F = ILB = (1.5)(2.5)(55×10⁻⁶) ≈ 2.1×10⁻⁴ N.", "Choose east = +x, north = +y and up = +z.", "(a) East crossed with north is up: force is 2.1×10⁻⁴ N upward.", "(b) Up crossed with north is west: the same magnitude acts westward.", "(c) North-to-south current is antiparallel to the field and F = 0. (d) The force is usually small compared with everyday mechanical forces."]]};for(const e of root.EmberChapter27DraftExercises){const v=reviewed[e.id];if(v){e.sv.steps=v[0];e.en.steps=v[1]}}})(window);

(function(root){'use strict';const reviewed={"27.31": [["(a) Ström åt höger och fält in i sidan ger magnetkraft uppåt.", "Lyftgränsen är ILB = mg, så I = (0,750·9,80)/(0,500·0,450) ≈ 32,7 A.", "Vid 25,0 Ω är spänningen V = IR ≈ 817 V.", "(b) Med samma ideala spänning och 2,0 Ω är begynnelseströmmen I = 817/2,0 ≈ 408 A.", "Direkt därefter är nettokraften ILB−mg och a = [408·0,500·0,450−0,750·9,80]/0,750 ≈ 113 m/s² uppåt i idealmodellen."], ["(a) Rightward current and field into the page give upward magnetic force.", "The lift threshold is ILB = mg, so I = (0.750·9.80)/(0.500·0.450) ≈ 32.7 A.", "At 25.0 Ω the voltage is V = IR ≈ 817 V.", "(b) At the same ideal voltage and 2.0 Ω, initial current is I = 817/2.0 ≈ 408 A.", "Immediately afterward net force is ILB−mg and a = [408·0.500·0.450−0.750·9.80]/0.750 ≈ 113 m/s² upward in the ideal model."]], "27.32": [["Tråden går genom centrum av det cirkulära fältområdet.", "Dess längd i fältet är därför diametern L = 2r = 0,0520 m.", "Ström och fält är vinkelräta.", "Kraftbeloppet är F = ILB.", "Insättning ger F = (11,0)(0,0520)(0,600) ≈ 0,343 N."], ["The wire passes through the center of the circular field region.", "Its length in the field is therefore the diameter L = 2r = 0.0520 m.", "Current and field are perpendicular.", "Force magnitude is F = ILB.", "Substitution gives F = (11.0)(0.0520)(0.600) ≈ 0.343 N."]], "27.33": [["(a) Staven behöver en magnetkraft uppåt.", "Ström åt höger kors fält in i sidan ger kraft uppåt; strömmen måste alltså lämna batteriets vänstra pol a, som är positiv.", "(b) Maximal ström är I = V/R = 175/5,00 = 35,0 A.", "Vid jämvikt är mg = ILB.", "m_max = ILB/g = (35,0)(0,600)(1,50)/9,80 ≈ 3,21 kg."], ["(a) The bar needs an upward magnetic force.", "Current to the right crossed with field into the page gives upward force; current must leave the battery’s left terminal a, which is positive.", "(b) Maximum current is I = V/R = 175/5.00 = 35.0 A.", "At equilibrium mg = ILB.", "m_max = ILB/g = (35.0)(0.600)(1.50)/9.80 ≈ 3.21 kg."]], "27.34": [["Alla fält är vågräta och vinkelräta mot den nedåtriktade strömmen.", "Kraftbeloppet är F = ILB = 2,60·0,0100·0,588 ≈ 0,0153 N i varje fall.", "Välj öster = +x, norr = +y och upp = +z.", "(a) Nedåt kors öster = söder. (b) Nedåt kors söder = väster.", "(c) Ett fält 30,0° söder om väster har komponenter längs −x och −y; kryss med −z ger kraft 30,0° väster om norr."], ["All fields are horizontal and perpendicular to downward current.", "Force magnitude is F = ILB = 2.60·0.0100·0.588 ≈ 0.0153 N in each case.", "Choose east = +x, north = +y and up = +z.", "(a) Down crossed with east is south. (b) Down crossed with south is west.", "(c) A field 30.0° south of west has components along −x and −y; crossing with −z gives force 30.0° west of north."]], "27.35": [["(a) Arean är A = 4,0 cm² = 4,0·10⁻⁴ m² och μ = NIA.", "Därför N = 0,194/(8,80·4,0·10⁻⁴) ≈ 55 varv.", "(b) Sedd från vänster pekar momentet mot observatören; högerhandsregeln ger moturs ström.", "(c) Momentet pekar vänster och fältet ut ur sidan, så de är vinkelräta och τ = μB = 0,194·45,0 = 8,73 N·m.", "Kryssprodukten μ × B pekar uppåt i sidan."], ["(a) Area is A = 4.0 cm² = 4.0×10⁻⁴ m² and μ = NIA.", "Therefore N = 0.194/(8.80·4.0×10⁻⁴) ≈ 55 turns.", "(b) Viewed from the left the moment points toward the observer; the right-hand rule gives counterclockwise current.", "(c) The moment points left and the field out of the page, so they are perpendicular and τ = μB = 0.194·45.0 = 8.73 N·m.", "The cross product μ × B points upward in the page."]], "27.36": [["Arean är A = 0,050·0,080 = 0,0040 m² och momentet μ = IA = 0,0264 A·m².", "(a) Normalen är vinkelrät mot B, så τ = μB ≈ 0,00634 N·m.", "(b) Det magnetiska momentets belopp är 0,0264 A·m².", "(c) Trådlängden är omkretsen L = 2(0,050+0,080) = 0,260 m.", "En cirkel omsluter största arean L²/(4π). Med normal vinkelrät mot B blir τ_max = IB L²/(4π) ≈ 0,00852 N·m."], ["Area is A = 0.050·0.080 = 0.0040 m² and moment μ = IA = 0.0264 A·m².", "(a) The normal is perpendicular to B, so τ = μB ≈ 0.00634 N·m.", "(b) Magnetic-moment magnitude is 0.0264 A·m².", "(c) Wire length is perimeter L = 2(0.050+0.080) = 0.260 m.", "A circle encloses maximum area L²/(4π). With its normal perpendicular to B, τ_max = IB L²/(4π) ≈ 0.00852 N·m."]], "27.37": [["(a) Övre och undre ledarna är parallella eller antiparallella med B och har ingen kraft.", "Strömmen i ab går uppåt: I vec(L) × vec(B) pekar in i sidan. Strömmen i cd går nedåt och kraften pekar ut ur sidan.", "(b) Kraften på ab verkar vid gångjärnet och ger inget moment kring det.", "Kraften på cd är F = ILB = 5,00·0,200·1,20 = 1,20 N.", "(c) Hävarmen är 0,350 m, så τ = 1,20·0,350 = 0,420 N·m. Momentvektorn pekar nedåt längs gångjärnet."], ["(a) The top and bottom wires are parallel or antiparallel to B and have no force.", "Current in ab flows upward: I vec(L) × vec(B) points into the page. Current in cd flows downward and force points out of the page.", "(b) Force on ab acts at the hinge and gives no torque about it.", "Force on cd is F = ILB = 5.00·0.200·1.20 = 1.20 N.", "(c) The lever arm is 0.350 m, so τ = 1.20·0.350 = 0.420 N·m. The torque vector points downward along the hinge."]], "27.38": [["En sluten strömslinga har noll nettokraft i ett homogent magnetfält.", "Momentet är vec(τ) = vec(μ) × vec(B), där μ = IA.", "(a) Den angivna strömmen ger μ ut ur sidan och B in i sidan. De är antiparallella, så både nettokraft och moment är noll.", "(b) Efter den angivna rotationen är vinkeln mellan μ och B 150°.", "Beloppet är τ = (1,95)(0,220)(0,350)(1,50)sin150° ≈ 0,113 N·m. Kryssprodukten ger moment uppåt längs axeln; nettokraften är fortsatt noll."], ["A closed current loop has zero net force in a uniform magnetic field.", "Torque is vec(τ) = vec(μ) × vec(B), with μ = IA.", "(a) The stated current gives μ out of the page and B into the page. They are antiparallel, so both net force and torque are zero.", "(b) After the specified rotation the angle between μ and B is 150°.", "Magnitude is τ = (1.95)(0.220)(0.350)(1.50)sin150° ≈ 0.113 N·m. The cross product gives upward torque along the axis; net force remains zero."]], "27.39": [["(a) Slingans magnetiska moment är normalt mot planet och B pekar uppåt i planet; μ × B ligger längs den vågräta centrumaxeln A₂.", "(b) Arean är 0,500 m² och momentet τ = IAB = 2,70·0,500·4,00 = 5,40 N·m.", "Trådens linjära densitet är λ = 0,270/[2(1,00+0,500)] = 0,0900 kg/m.", "De vågräta sidorna bidrar med 2λ(1,00)(0,250)² och de lodräta med 2λ(0,500)³/12. Summan är I_rot = 0,013125 kg·m².", "Begynnelseaccelerationen är α = τ/I_rot ≈ 411 rad/s² kring A₂."], ["(a) The loop’s magnetic moment is normal to its plane while B points upward in the plane, so μ × B lies along horizontal center axis A₂.", "(b) Area is 0.500 m² and torque τ = IAB = 2.70·0.500·4.00 = 5.40 N·m.", "Wire linear density is λ = 0.270/[2(1.00+0.500)] = 0.0900 kg/m.", "The horizontal sides contribute 2λ(1.00)(0.250)² and the vertical sides 2λ(0.500)³/12. Their sum is I_rot = 0.013125 kg·m².", "Initial acceleration is α = τ/I_rot ≈ 411 rad/s² about A₂."]], "27.40": [["(a) Högerhandsregeln ger vec(μ)_A = −NIA k för medurs ström och vec(μ)_B = +NIA k för moturs ström sedd från +z.", "(b) Momenten är antiparallella respektive parallella med fältet, så vec(τ) = vec(μ) × vec(B) = 0 för båda.", "(c) Från U = −vec(μ) · vec(B) fås U_A = +NIAB och U_B = −NIAB.", "(d) A ligger vid ett energimaximum och är instabilt för små vridningar.", "B ligger vid ett minimum och är stabilt."], ["(a) The right-hand rule gives vec(μ)_A = −NIA k for clockwise current and vec(μ)_B = +NIA k for counterclockwise current viewed from +z.", "(b) The moments are antiparallel and parallel to the field respectively, so vec(τ) = vec(μ) × vec(B) = 0 for both.", "(c) From U = −vec(μ) · vec(B), U_A = +NIAB and U_B = −NIAB.", "(d) A lies at an energy maximum and is unstable to small rotations.", "B lies at a minimum and is stable."]]};for(const e of root.EmberChapter27DraftExercises){const v=reviewed[e.id];if(v){e.sv.steps=v[0];e.en.steps=v[1]}}})(window);

(function(root){'use strict';const reviewed={"27.41": [["Använd vec(τ) = vec(μ) × vec(B) och U = −vec(μ) · vec(B), med μ = NIA och vec(B) = B j.", "(a) μ längs +z ger τ = −NIAB i och U = 0.", "(b) μ längs +y ger τ = 0 och U = −NIAB.", "(c) μ längs −z ger τ = +NIAB i och U = 0.", "(d) μ längs −y ger τ = 0 och U = +NIAB."], ["Use vec(τ) = vec(μ) × vec(B) and U = −vec(μ) · vec(B), with μ = NIA and vec(B) = B j.", "(a) μ along +z gives τ = −NIAB i and U = 0.", "(b) μ along +y gives τ = 0 and U = −NIAB.", "(c) μ along −z gives τ = +NIAB i and U = 0.", "(d) μ along −y gives τ = 0 and U = +NIAB."]], "27.42": [["Magnetisk potentiell energi är U = −μB cosθ.", "Antiparallellt läge har θ = 180° och U_i = +μB.", "Parallellt läge har θ = 0° och U_f = −μB.", "Ändringen är ΔU = U_f−U_i = −2μB.", "Med μ = 1,46 A·m² och B = 0,805 T fås ΔU ≈ −2,35 J."], ["Magnetic potential energy is U = −μB cosθ.", "Antiparallel means θ = 180° and U_i = +μB.", "Parallel means θ = 0° and U_f = −μB.", "The change is ΔU = U_f−U_i = −2μB.", "With μ = 1.46 A·m² and B = 0.805 T, ΔU ≈ −2.35 J."]], "27.43": [["(a) Fältlindningen ligger direkt över 230 V: I_f = 230/215 ≈ 1,07 A.", "(b) Strömfördelningen ger I_r = 8,67−I_f ≈ 7,60 A.", "(c) Rotorekvationen är V = ε_mot+I_rR_r.", "Därför ε_mot = 230−(7,60)(6,3) ≈ 182 V.", "(d) Omvandlad mekanisk effekt före mekaniska förluster är ε_motI_r ≈ 1,38 kW."], ["(a) The field winding is directly across 230 V: I_f = 230/215 ≈ 1.07 A.", "(b) Current division gives I_r = 8.67−I_f ≈ 7.60 A.", "(c) The rotor equation is V = ε_back+I_rR_r.", "Therefore ε_back = 230−(7.60)(6.3) ≈ 182 V.", "(d) Converted mechanical power before mechanical losses is ε_backI_r ≈ 1.38 kW."]], "27.44": [["(a) Slinglagen ger I = (V−ε_mot)/R = (230−200)/4,0 = 7,5 A.", "(b) Elektrisk ineffekt är VI = 230·7,5 = 1725 W.", "(c) Utvecklad mekanisk effekt är ε_motI = 200·7,5 = 1500 W.", "Resistiv värmeeffekt är I²R = 225 W.", "Kontroll: 1500+225 = 1725 W i den idealiserade modellen."], ["(a) The loop rule gives I = (V−ε_back)/R = (230−200)/4.0 = 7.5 A.", "(b) Electrical input power is VI = 230·7.5 = 1725 W.", "(c) Developed mechanical power is ε_backI = 200·7.5 = 1500 W.", "Resistive heating is I²R = 225 W.", "Check: 1500+225 = 1725 W in the idealized model."]], "27.45": [["(a) Tvärsnittsarean är A = (0,0118)(0,00023) m².", "Ur I = neA|v_d| fås |v_d| = 4,72·10⁻³ m/s; elektrondriften pekar längs −x.", "(b) Stationär tvärkraft ger vec(E)_H = −vec(v)_d × vec(B).", "Eftersom (−x) × (+y) = −z pekar Hallfältet +z och har belopp |v_d|B = 4,48·10⁻³ V/m.", "(c) Över bredden 0,0118 m är |V_H| = E_H·0,0118 = 52,9 μV. Potentialen avtar i +z-riktningen."], ["(a) Cross-sectional area is A = (0.0118)(0.00023) m².", "From I = neA|v_d|, |v_d| = 4.72×10⁻³ m/s; electron drift points along −x.", "(b) Stationary transverse force gives vec(E)_H = −vec(v)_d × vec(B).", "Since (−x) × (+y) = −z, the Hall field points +z and has magnitude |v_d|B = 4.48×10⁻³ V/m.", "(c) Across width 0.0118 m, |V_H| = E_H·0.0118 = 52.9 μV. Potential decreases in the +z direction."]], "27.46": [["För en enda bärartyp med B längs bandets tjocklek t gäller |V_H| = IB/(net).", "Lös ut n = IB/(et|V_H|).", "Omvandla t = 0,23·10⁻³ m och |V_H| = 131·10⁻⁶ V.", "Använd I = 78,0 A och B = 2,29 T.", "Enbärarmodellen ger n ≈ 3,70·10²⁸ m⁻³."], ["For a single carrier type with B along the ribbon thickness t, |V_H| = IB/(net).", "Solve n = IB/(et|V_H|).", "Convert t = 0.23×10⁻³ m and |V_H| = 131×10⁻⁶ V.", "Use I = 78.0 A and B = 2.29 T.", "The single-carrier model gives n ≈ 3.70×10²⁸ m⁻³."]], "27.47": [["Vinkelfrekvensen i xy-planet är ω = qB/m = 30,0 rad/s och radien r = v₀/ω = 1,00 m.", "För positiv laddning i +z-fält är v_x = v₀cosωt och v_y = −v₀sinωt.", "Integration med x(0) = 0 och y(0) = 1,00 m ger x = r sinωt, y = 1,00+r(cosωt−1).", "Längs z är a_z = qE/m = 450 m/s², så z = a_zt²/2 och v_z = a_zt. Vid 0,0200 s är ωt = 0,600 rad.", "(a) Positionen är (0,565; 0,825; 0,0900) m. (b) xy-farten är 30,0 m/s och v_z = 9,00 m/s, så v = √(30,0²+9,00²) ≈ 31,3 m/s."], ["The xy-plane angular frequency is ω = qB/m = 30.0 rad/s and radius r = v₀/ω = 1.00 m.", "For positive charge in a +z field, v_x = v₀cosωt and v_y = −v₀sinωt.", "Integrating with x(0) = 0 and y(0) = 1.00 m gives x = r sinωt, y = 1.00+r(cosωt−1).", "Along z, a_z = qE/m = 450 m/s², so z = a_zt²/2 and v_z = a_zt. At 0.0200 s, ωt = 0.600 rad.", "(a) Position is (0.565, 0.825, 0.0900) m. (b) xy speed remains 30.0 m/s and v_z = 9.00 m/s, so v = √(30.0²+9.00²) ≈ 31.3 m/s."]], "27.48": [["Med vec(B) = B_x i är kryssprodukten vec(v) × vec(B) = B_x(v_z j−v_y k).", "Hastighetens x-komponent bidrar inte.", "F_x = 0.", "F_y = qB_xv_z = (9,41·10⁻⁸)(0,660)(5,88·10⁴) ≈ +3,65·10⁻³ N.", "F_z = −qB_xv_y = −(9,41·10⁻⁸)(0,660)(−3,14·10⁴) ≈ +1,95·10⁻³ N."], ["With vec(B) = B_x i, the cross product is vec(v) × vec(B) = B_x(v_z j−v_y k).", "The x velocity component contributes nothing.", "F_x = 0.", "F_y = qB_xv_z = (9.41×10⁻⁸)(0.660)(5.88×10⁴) ≈ +3.65×10⁻³ N.", "F_z = −qB_xv_y = −(9.41×10⁻⁸)(0.660)(−3.14×10⁴) ≈ +1.95×10⁻³ N."]], "27.49": [["(a) I masscentrumsystemet är totala begynnelseenergin 2(mv²/2) = mv².", "Vid närmaste avstånd har den blivit elektrisk potentiell energi ke²/r_min.", "Därför v = √[ke²/(mr_min)] ≈ 8,31·10⁶ m/s.", "(b) Cirkelns radie är 2,60/2 = 1,30 m och evB = mv²/r.", "Alltså B = mv/(er) ≈ 0,133 T."], ["(a) In the center-of-mass frame total initial kinetic energy is 2(mv²/2) = mv².", "At closest approach it has become electric potential energy ke²/r_min.", "Thus v = √[ke²/(mr_min)] ≈ 8.31×10⁶ m/s.", "(b) Circle radius is 2.60/2 = 1.30 m and evB = mv²/r.", "Therefore B = mv/(er) ≈ 0.133 T."]], "27.50": [["(a) Ett varv har längden 2πr.", "Perioden är T = 2πr/v ≈ 1,5·10⁻¹⁶ s.", "(b) Laddningsbeloppet e passerar per varv, så I = e/T ≈ 1,1 mA.", "Konventionell ström går motsatt elektronens rörelse.", "(c) Momentets belopp är μ = IA = Iπr² ≈ 9,3·10⁻²⁴ A·m²."], ["(a) One orbit has length 2πr.", "The period is T = 2πr/v ≈ 1.5×10⁻¹⁶ s.", "(b) Charge magnitude e passes per revolution, so I = e/T ≈ 1.1 mA.", "Conventional current is opposite electron motion.", "(c) Moment magnitude is μ = IA = Iπr² ≈ 9.3×10⁻²⁴ A·m²."]]};for(const e of root.EmberChapter27DraftExercises){const v=reviewed[e.id];if(v){e.sv.steps=v[0];e.en.steps=v[1]}}})(window);

(function(root){'use strict';const reviewed={"27.51": [["Accelerationsenergin ger qΔV = mv²/2.", "Magnetisk cirkelrörelse ger R = mv/(qB).", "Eliminera v: R² = [2m/(qB²)]ΔV.", "Grafens lutning är alltså s = 2m/(qB²).", "q/m = 2/(sB²) = 2/[(1,04·10⁻⁶)(0,200)²] ≈ 4,81·10⁷ C/kg."], ["Acceleration energy gives qΔV = mv²/2.", "Magnetic circular motion gives R = mv/(qB).", "Eliminate v: R² = [2m/(qB²)]ΔV.", "Graph slope is therefore s = 2m/(qB²).", "q/m = 2/(sB²) = 2/[(1.04×10⁻⁶)(0.200)²] ≈ 4.81×10⁷ C/kg."]], "27.52": [["I den ickerelativistiska modellen är v = qBr/m och K = q²B²r²/(2m).", "(a) Protonens energi är K_p = 9,93·10⁻¹³ J = 6,21 MeV.", "(b) Perioden är T = 2πm/(qB) ≈ 8,20·10⁻⁸ s.", "(c) Vid fast radie är K ∝ B², så dubbla energin kräver B_ny = √2·0,80 ≈ 1,13 T.", "(d) Alfapartikelns q och m ger K_α = 9,99·10⁻¹³ J = 6,25 MeV, nästan lika eftersom q²/m är nästan samma."], ["In the nonrelativistic model v = qBr/m and K = q²B²r²/(2m).", "(a) Proton energy is K_p = 9.93×10⁻¹³ J = 6.21 MeV.", "(b) Period is T = 2πm/(qB) ≈ 8.20×10⁻⁸ s.", "(c) At fixed radius K ∝ B², so twice the energy requires B_new = √2·0.80 ≈ 1.13 T.", "(d) Alpha-particle q and m give K_α = 9.99×10⁻¹³ J = 6.25 MeV, nearly equal because q²/m is almost the same."]], "27.53": [["Hastighetsselektorn ger v = E/B = (1,89·10⁴)/0,675 = 2,80·10⁴ m/s.", "I analysfältet är r = mv/(eB).", "Närliggande isotoper skiljer sig med Δm = 2u = 3,32·10⁻²⁷ kg, så Δr = Δm v/(eB).", "Efter en halvcirkel är linjeavståndet 2Δr ≈ 1,72 mm för vardera intilliggande paret.", "De yttersta linjerna ligger 3,44 mm från varandra."], ["The velocity selector gives v = E/B = (1.89×10⁴)/0.675 = 2.80×10⁴ m/s.", "In the analyzing field r = mv/(eB).", "Adjacent isotopes differ by Δm = 2u = 3.32×10⁻²⁷ kg, so Δr = Δm v/(eB).", "After a semicircle line spacing is 2Δr ≈ 1.72 mm for either adjacent pair.", "The outer lines are 3.44 mm apart."]], "27.54": [["(a) Energi och cirkelrörelse ger qV = mv²/2 och R = mv/(qB).", "Sätt in v = qBR/m i energiekvationen: m = qB²R²/(2V).", "(b) Lös V = qB²R²/(2m). Med q = e och m = 12u blir V ≈ 22,6 kV.", "(c) Vid samma v, q och B gäller r ∝ m. Radieskillnaden är ΔR = R(14−12)/12 och separation efter halvcirklar är 2ΔR = 0,167 m.", "En separation på 16,7 cm är stor i många detektorer, men faktisk upplösning beror på strålbredd och instrument."], ["(a) Energy and circular motion give qV = mv²/2 and R = mv/(qB).", "Substitute v = qBR/m into the energy equation: m = qB²R²/(2V).", "(b) Solve V = qB²R²/(2m). With q = e and m = 12u, V ≈ 22.6 kV.", "(c) At equal v, q and B, r ∝ m. Radius difference is ΔR = R(14−12)/12 and separation after semicircles is 2ΔR = 0.167 m.", "A 16.7 cm separation is large on many detector scales, but actual resolution depends on beam width and instrument."]], "27.55": [["Staven påverkas av tyngden Mg nedåt, normalkraft N vinkelrätt ut från planet och vågrät magnetkraft F_B = ILB.", "Välj ström så magnetkraften pekar mot uppförsidan; i den visade sidovyn innebär det ström in i sidan.", "Upplösning längs planet ger ILB cosθ = Mg sinθ.", "Därför I = Mg tanθ/(LB).", "Jämvikt vinkelrätt mot planet ger N = Mg cosθ+ILB sinθ = Mg/cosθ."], ["The bar experiences weight Mg downward, normal force N outward from the incline, and horizontal magnetic force F_B = ILB.", "Choose current so magnetic force points toward the uphill side; in the shown side view current is into the page.", "Resolving along the plane gives ILB cosθ = Mg sinθ.", "Thus I = Mg tanθ/(LB).", "Perpendicular equilibrium gives N = Mg cosθ+ILB sinθ = Mg/cosθ."]], "27.56": [["När S sluts ligger 20,0 Ω-resistorn parallellt med den rörliga staven på 20,0 Ω: R_p = 10,0 Ω.", "Med 36,0 Ω i serie är totalströmmen 230/46,0 = 5,00 A.", "De lika grenarna leder vardera 2,50 A.", "Strömmen i staven pekar nedåt i figuren och B in i sidan, så I vec(L) × vec(B) pekar åt höger.", "F = ILB = 2,50·0,850·1,60 = 3,40 N. Massan är m = 2,60/9,80 = 0,265 kg och begynnelseaccelerationen a ≈ 12,8 m/s² åt höger."], ["Closing S puts the 20.0 Ω resistor in parallel with the 20.0 Ω bar, giving R_p = 10.0 Ω.", "With 36.0 Ω in series total current is 230/46.0 = 5.00 A.", "The equal branches each carry 2.50 A.", "Bar current points downward in the figure and B into the page, so I vec(L) × vec(B) points right.", "F = ILB = 3.40 N and m = 2.60/9.80 = 0.265 kg, so initial acceleration is about 12.8 m/s² rightward."]], "27.57": [["(a) För ¹²C är radien 0,250/2 = 0,125 m.", "Därför B = m₁₂v/(er₁₂) ≈ 8,45 mT.", "(b) Samma fart, laddning och B ger r ∝ m.", "¹³C-diametern är d₁₃ = 25,0 cm·(2,16/1,99) ≈ 27,1 cm.", "(c) Efter halvcirklar är träffseparationen diameterskillnaden 2,14 cm. Den är stor för en smal stråle, men faktisk upplösning beror på instrumentet."], ["(a) For ¹²C radius is 0.250/2 = 0.125 m.", "Thus B = m₁₂v/(er₁₂) ≈ 8.45 mT.", "(b) Equal speed, charge and B give r ∝ m.", "The ¹³C diameter is d₁₃ = 25.0 cm·(2.16/1.99) ≈ 27.1 cm.", "(c) After semicircles impact separation is the diameter difference 2.14 cm. It is large for a narrow beam, but actual resolution depends on the instrument."]], "27.58": [["Perioden är T = 2π/ω.", "Hela laddningen passerar en punkt en gång per varv, så I = q/T = qω/(2π).", "Ringens magnetiska moment är μ = IπR² = qωR²/2.", "Eftersom B ligger i ringens plan är μ vinkelrätt mot B.", "Vridmomentets belopp är τ = μB = qωR²B/2."], ["The period is T = 2π/ω.", "The full charge passes a point once per revolution, so I = q/T = qω/(2π).", "The ring’s magnetic moment is μ = IπR² = qωR²/2.", "Since B lies in the ring plane, μ is perpendicular to B.", "Torque magnitude is τ = μB = qωR²B/2."]], "27.59": [["(a) Ström och fält är vinkelräta, så F = ILB längs rälsen.", "Riktningen ges av I vec(L) × vec(B).", "(b) Konstant kraft från vila utför arbetet Fd = mv²/2, vilket ger d = mv²/(2ILB).", "(c) F = (2400)(0,51)(0,82) ≈ 1,00·10³ N.", "Med v = 11,2·10³ m/s och m = 30 kg fås d ≈ 1,87·10⁶ m, cirka 1870 km i den förenklade modellen."], ["(a) Current and field are perpendicular, so F = ILB along the rails.", "Direction is given by I vec(L) × vec(B).", "(b) Constant force from rest does work Fd = mv²/2, giving d = mv²/(2ILB).", "(c) F = (2400)(0.51)(0.82) ≈ 1.00×10³ N.", "With v = 11.2×10³ m/s and m = 30 kg, d ≈ 1.87×10⁶ m, about 1870 km in the simplified model."]], "27.60": [["vec(F) = I vec(L) × vec(B), med vec(L) = 0,300 k m.", "Eftersom k × i = j och k × j = −i är vec(F) = IL(−B_y i+B_x j).", "IL = 6,60·0,300 = 1,98 A·m.", "(a) Komponenterna blir (1,94; −0,398; 0) N; B_z bidrar inte.", "(b) |F| = √(1,94²+0,398²) ≈ 1,98 N."], ["vec(F) = I vec(L) × vec(B), with vec(L) = 0.300 k m.", "Since k × i = j and k × j = −i, vec(F) = IL(−B_y i+B_x j).", "IL = 6.60·0.300 = 1.98 A·m.", "(a) Components are (1.94, −0.398, 0) N; B_z contributes nothing.", "(b) |F| = √(1.94²+0.398²) ≈ 1.98 N."]]};for(const e of root.EmberChapter27DraftExercises){const v=reviewed[e.id];if(v){e.sv.steps=v[0];e.en.steps=v[1]}}})(window);

(function(root){'use strict';const reviewed={"27.61": [["I homogent fält integreras krafterna längs kurvan till vec(F) = I[vec(r)_b−vec(r)_a] × vec(B).", "Ändpunktsförskjutningen är (0,200 i−0,200 j) m.", "(a) Med B = 0,800 k T är vec(F) = (−0,800 i−0,800 j) N.", "Beloppet är 1,13 N mitt emellan −x och −y.", "(b) Med B = 0,800 i T är vec(F) = +0,800 k N, alltså 0,800 N längs +z."], ["In a uniform field forces along the curve integrate to vec(F) = I[vec(r)_b−vec(r)_a] × vec(B).", "Endpoint displacement is (0.200 i−0.200 j) m.", "(a) With B = 0.800 k T, vec(F) = (−0.800 i−0.800 j) N.", "Magnitude is 1.13 N halfway between −x and −y.", "(b) With B = 0.800 i T, vec(F) = +0.800 k N, or 0.800 N along +z."]], "27.62": [["(a) Välj exempelvis navdiametern D = 0,20 m; detta är en uppskattning.", "(b) Tolv rotordiametrar upptar en tredjedel av omkretsen: d = πD/36 ≈ 0,0175 m.", "(c) Anta att vardera rotorn ger 1,4/12 N·m. För en plan spole med moment vinkelrätt mot fältet ger τ = μB att μ ≈ 0,117 A·m².", "(d) Med I = 0,75/12 A och A = πd²/4 blir N = μ/(IA) ≈ 7800 varv.", "Bokens fält parallellt med rotoraxeln kräver försiktighet: om det också är parallellt med en plan spoles magnetiska moment är τ = μB sin0° = 0. Varvtalsuppskattningen gäller därför bara den uttryckligt antagna vinkelräta orienteringen."], ["(a) Choose, for example, hub diameter D = 0.20 m; this is an estimate.", "(b) Twelve rotor diameters occupy one third of the circumference: d = πD/36 ≈ 0.0175 m.", "(c) Assume each rotor supplies 1.4/12 N·m. For a planar coil with moment perpendicular to the field, τ = μB gives μ ≈ 0.117 A·m².", "(d) With I = 0.75/12 A and A = πd²/4, N = μ/(IA) ≈ 7800 turns.", "The book’s field parallel to the rotor axis needs care: if that also means parallel to a planar coil’s magnetic moment, τ = μB sin0° = 0. The turn estimate therefore applies only to the explicitly assumed perpendicular orientation."]], "27.63": [["Tvärsnittet är A = πd²/4 = 1,96·10⁻⁵ m². Jämvikt per längdenhet kräver IB_h = ρAg.", "(a) Jordfältets vågräta komponent är B_h = 50 μT cos45° = 35,4 μT, vilket ger I = ρAg/B_h ≈ 4,84·10⁴ A.", "(b) Detta överstiger kraftigt smältströmmen 900 A.", "(c) Vid 900 A krävs B_h = ρAg/900 ≈ 1,90 mT.", "(d) Med I = 10 A, L = 0,10 m och B = 1,0 T är magnetkraften 1,00 N. Staven väger ρALg = 0,171 N, så 0,829 N återstår för extra vikt."], ["Cross section is A = πd²/4 = 1.96×10⁻⁵ m². Equilibrium per length requires IB_h = ρAg.", "(a) Earth’s horizontal field component is B_h = 50 μT cos45° = 35.4 μT, giving I = ρAg/B_h ≈ 4.84×10⁴ A.", "(b) This far exceeds the 900 A fusing current.", "(c) At 900 A the required B_h is ρAg/900 ≈ 1.90 mT.", "(d) With I = 10 A, L = 0.10 m and B = 1.0 T, magnetic force is 1.00 N. The bar weighs ρALg = 0.171 N, leaving 0.829 N for extra weight."]], "27.64": [["Arean är A = 0,0800·0,0600 m² och μ = IA = 0,0720 A·m².", "Den angivna strömmen ger vec(μ) = μ(sin30° i−cos30° k).", "(a) För vec(B) = 0,48 i T är magnetmomentet vec(τ)_B = −0,0299 j N·m. Hållmomentet är motsatt: +0,0299 j N·m.", "(b) För vec(B) = −0,48 k T är vec(τ)_B = +0,0173 j N·m och hållmomentet −0,0173 j N·m.", "(c) En sluten slinga i homogent fält har noll nettokraft, så momentet är oförändrat kring den parallella axeln genom centrum."], ["Area is A = 0.0800·0.0600 m² and μ = IA = 0.0720 A·m².", "The stated current gives vec(μ) = μ(sin30° i−cos30° k).", "(a) For vec(B) = 0.48 i T, magnetic torque is vec(τ)_B = −0.0299 j N·m. Holding torque is opposite: +0.0299 j N·m.", "(b) For vec(B) = −0.48 k T, vec(τ)_B = +0.0173 j N·m and holding torque −0.0173 j N·m.", "(c) A closed loop in a uniform field has zero net force, so torque is unchanged about the parallel axis through its center."]], "27.65": [["Omkretsen är 2(6,00+8,00) = 28,0 cm och massan 28,0·0,16 g = 0,00448 kg.", "För en jämn slinga ligger masscentrum 0,0400 m från axeln.", "Vid 30,0° från vertikalen är tyngdmomentets belopp Mg(0,0400)sin30°.", "Magnetmomentet är μ = IA med A = 0,0600·0,0800 m², och balans kräver IAB cos30° = Mg(0,0400)sin30°.", "Då B ≈ 0,0237 T. För angiven ström och lutning pekar B längs +y för att motverka tyngdmomentet."], ["Perimeter is 2(6.00+8.00) = 28.0 cm and mass is 28.0·0.16 g = 0.00448 kg.", "For a uniform loop its center of mass is 0.0400 m from the pivot.", "At 30.0° from vertical, gravitational torque magnitude is Mg(0.0400)sin30°.", "Magnetic moment is μ = IA with A = 0.0600·0.0800 m², and balance requires IAB cos30° = Mg(0.0400)sin30°.", "Then B ≈ 0.0237 T. For the stated current and tilt B points along +y to oppose gravity."]], "27.66": [["Ett längdelement dx på avstånd x får kraften dF = IB dx vinkelrätt mot staven.", "(a) Dess moment om a är dτ = x dF = IBx dx, moturs för angiven ström och fält.", "(b) Integrera från 0 till L: τ = ∫₀ᴸ IBx dx.", "Därmed τ = IBL²/2.", "(c) Totalkraften är IBL. Applicerad i mittpunkten ger den IBL·L/2, samma resultat."], ["A length element dx at distance x experiences force dF = IB dx perpendicular to the bar.", "(a) Its torque about a is dτ = x dF = IBx dx, counterclockwise for the stated current and field.", "(b) Integrate from 0 to L: τ = ∫₀ᴸ IBx dx.", "Thus τ = IBL²/2.", "(c) Total force is IBL. Applied at the midpoint it gives IBL·L/2, the same result."]], "27.67": [["För varje rakt segment är vec(F) = I vec(L) × vec(B), med B = 3,00 j T.", "(a) På PQ är strömmen parallell med fältet: F_PQ = 0. QR:s +x-komponent ger F_QR = +12,0 k N och RP:s −x-komponent F_RP = −12,0 k N.", "(b) Summan är noll.", "(c) QR-kraften kan verka i sin mittpunkt, 0,300 m från axeln PR, vilket ger τ_x = 0,300·12,0 = +3,60 N·m. PQ saknar kraft och RP ligger på axeln.", "(d) A = 0,800·0,600/2 = 0,240 m² och strömmen ger vec(μ) = −IA k. Då vec(μ) × vec(B) = +3,60 i N·m, samma resultat. (e) Q rör sig ut ur sidan."], ["For each straight segment vec(F) = I vec(L) × vec(B), with B = 3.00 j T.", "(a) On PQ current is parallel to the field: F_PQ = 0. QR’s +x component gives F_QR = +12.0 k N and RP’s −x component F_RP = −12.0 k N.", "(b) The sum is zero.", "(c) The QR force may act at its midpoint, 0.300 m from axis PR, giving τ_x = 0.300·12.0 = +3.60 N·m. PQ has no force and RP lies on the axis.", "(d) A = 0.800·0.600/2 = 0.240 m² and current gives vec(μ) = −IA k. Then vec(μ) × vec(B) = +3.60 i N·m, the same result. (e) Point Q moves out of the page."]], "27.68": [["Med vec(B) = −3,00 k T används I vec(L) × vec(B) för varje sida.", "På PQ fås F_PQ = −9,00 i N.", "På QR fås F_QR = (9,00 i+12,0 j) N och på RP F_RP = −12,0 j N.", "Summan är noll. Alla krafter ligger i triangelns plan, så momentet om axeln PR saknar x-komponent.", "Slingans magnetiska moment pekar också in i sidan, parallellt med B: vec(μ) × vec(B) = 0. Q drivs varken in i eller ut ur sidan."], ["With vec(B) = −3.00 k T use I vec(L) × vec(B) on each side.", "On PQ, F_PQ = −9.00 i N.", "On QR, F_QR = (9.00 i+12.0 j) N and on RP, F_RP = −12.0 j N.", "Their sum is zero. All forces lie in the triangle’s plane, so torque about axis PR has no x component.", "The loop’s magnetic moment also points into the page, parallel to B: vec(μ) × vec(B) = 0. Q is driven neither into nor out of the page."]], "27.69": [["Fältet har radiell komponent B_r = B sin60°.", "Axiella kraftbidrag runt spolen adderas medan radiella bidrag tar ut varandra genom symmetri.", "Total trådlängd är Nπd.", "F = NIπd B sin60° ≈ 0,429 N.", "Högerhandsregeln för den angivna strömmen och det utåtriktade radiella fältet ger kraft längs −y."], ["The field has radial component B_r = B sin60°.", "Axial force contributions around the coil add while radial contributions cancel by symmetry.", "Total wire length is Nπd.", "F = NIπd B sin60° ≈ 0.429 N.", "The right-hand rule for the stated current and outward radial field gives force along −y."]], "27.70": [["Tyngden verkar i stavens mitt och ger medurs moment mg(L/2)cos30°.", "Magnetkraften är jämnt fördelad längs staven.", "Integration kring leden ger moturs moment IBL²/2 om strömmen går från leden till den fria änden.", "Jämvikt kräver IBL²/2 = mg(L/2)cos30°.", "Därför I = mg cos30°/(BL) ≈ 2,26 A från leden mot fria änden."], ["Weight acts at the bar’s midpoint and gives clockwise torque mg(L/2)cos30°.", "Magnetic force is uniformly distributed along the bar.", "Integration about the pivot gives counterclockwise torque IBL²/2 if current runs from pivot to free end.", "Equilibrium requires IBL²/2 = mg(L/2)cos30°.", "Therefore I = mg cos30°/(BL) ≈ 2.26 A from pivot toward the free end."]]};for(const e of root.EmberChapter27DraftExercises){const v=reviewed[e.id];if(v){e.sv.steps=v[0];e.en.steps=v[1]}}})(window);

(function(root){'use strict';const reviewed={"27.71": [["(a) I yz-planet är B_y = B₀z/L och B_z = B₀y/L.", "Fältlinjer uppfyller dy/dz = z/y och därmed y²−z² = konstant; pilarna följer det lokala fältet.", "(b) På slingan är z = 0 och vec(B) = (B₀y/L)k. Integrera I dvec(ℓ) × vec(B) längs varje sida.", "Krafterna blir vänster +IB₀L i/2, höger −IB₀L i/2, övre −IB₀L j och undre noll.", "(c) x-krafterna tar ut varandra. Nettokraften är −IB₀L j: ett inhomogent fält kan ge en sluten slinga nettokraft."], ["(a) In the yz plane B_y = B₀z/L and B_z = B₀y/L.", "Field lines obey dy/dz = z/y and hence y²−z² = constant; arrows follow the local field.", "(b) On the loop z = 0 and vec(B) = (B₀y/L)k. Integrate I dvec(ℓ) × vec(B) along each side.", "The forces are left +IB₀L i/2, right −IB₀L i/2, top −IB₀L j and bottom zero.", "(c) The x forces cancel. Net force is −IB₀L j: a nonuniform field can exert net force on a closed loop."]], "27.72": [["Ta moment kring leden P; ledens kraft ger inget moment där.", "Den vågräta linspänningen T ger moturs moment TL sinθ.", "Tyngden ger medurs moment mg(L/2)cosθ.", "Strömmen går mot leden och B in i sidan; magnetkraften ger också medurs moment IBL²/2.", "Jämvikt ger T = [mg cosθ/2+IBL/2]/sinθ ≈ 0,472 N."], ["Take torques about hinge P; its force contributes no torque there.", "Horizontal string tension T gives counterclockwise torque TL sinθ.", "Weight gives clockwise torque mg(L/2)cosθ.", "Current runs toward the hinge and B into the page; magnetic force also gives clockwise torque IBL²/2.", "Equilibrium gives T = [mg cosθ/2+IBL/2]/sinθ ≈ 0.472 N."]], "27.75": [["(a) Medurs ström sedd från +z ger vec(μ) = −IA k enligt högerhandsregeln.", "(b) Kryssprodukten är vec(μ) × vec(B) = IA(B_y i−B_x j).", "Jämförelse med D(4i−3j) ger B_x = 3D/(IA) och B_y = 4D/(IA).", "Givet fältbelopp ger B_z² = [13²−3²−4²]D²/(IA)², så |B_z| = 12D/(IA).", "U = −vec(μ) · vec(B) = IA B_z är negativ. Därför B_z = −12D/(IA)."], ["(a) Clockwise current viewed from +z gives vec(μ) = −IA k by the right-hand rule.", "(b) The cross product is vec(μ) × vec(B) = IA(B_y i−B_x j).", "Comparing with D(4i−3j) gives B_x = 3D/(IA) and B_y = 4D/(IA).", "The stated magnitude gives B_z² = [13²−3²−4²]D²/(IA)², so |B_z| = 12D/(IA).", "U = −vec(μ) · vec(B) = IA B_z is negative. Therefore B_z = −12D/(IA)."]], "27.76": [["(a) Kombination av qV = mv²/2 och R = mv/(qB) ger R² = [2m/(qB²)]V. Rita R² mot V.", "(b) Linjär regression med fritt intercept för de fem mätningarna ger lutningen s = 4,0213·10⁻⁶ m²/V.", "Därmed q/m = 2/(B²s) ≈ 7,96·10⁶ C/kg.", "(c) v = √[2(q/m)V] = √[2(7,96·10⁶)(2,00·10⁴)] ≈ 5,64·10⁵ m/s.", "(d) Vid samma massa, spänning och B gäller R ∝ 1/√q. Dubbel laddning ger R = 21,2/√2 ≈ 15,0 cm."], ["(a) Combining qV = mv²/2 and R = mv/(qB) gives R² = [2m/(qB²)]V. Plot R² versus V.", "(b) Linear regression with free intercept for the five measurements gives slope s = 4.0213×10⁻⁶ m²/V.", "Hence q/m = 2/(B²s) ≈ 7.96×10⁶ C/kg.", "(c) v = √[2(q/m)V] = √[2(7.96×10⁶)(2.00×10⁴)] ≈ 5.64×10⁵ m/s.", "(d) At the same mass, voltage and B, R ∝ 1/√q. Doubling charge gives R = 21.2/√2 ≈ 15.0 cm."]], "27.77": [["(a) Ingen avböjning ger E = vB. Accelerationen ger eV = mv²/2, så E² = (2eB²/m)V och grafen är linjär.", "(b) Ungefärlig grafavläsning ger s ≈ (8,00·10¹⁰)/400 = 2,00·10⁸ i SI-enheter.", "Då m = 2eB²/s ≈ 1,85·10⁻²⁸ kg.", "(c) Plattspänningen är Ed = (2,00·10⁵)(0,00600) = 1,20 kV.", "(d) Vid 400 V ger grafen E ≈ √(8,00·10¹⁰) V/m och v = E/B ≈ 8,32·10⁵ m/s. Grafvärdena är uppskattningar."], ["(a) No deflection gives E = vB. Acceleration gives eV = mv²/2, so E² = (2eB²/m)V and the graph is linear.", "(b) An approximate graph reading gives s ≈ (8.00×10¹⁰)/400 = 2.00×10⁸ in SI units.", "Then m = 2eB²/s ≈ 1.85×10⁻²⁸ kg.", "(c) Plate voltage is Ed = (2.00×10⁵)(0.00600) = 1.20 kV.", "(d) At 400 V the graph gives E ≈ √(8.00×10¹⁰) V/m and v = E/B ≈ 8.32×10⁵ m/s. Graph-derived values are estimates."]], "27.78": [["(a) I den ickerelativistiska modellen är f = (q/m)B/(2π).", "Grafens ungefärliga lutning är (3,08·10⁶)/0,400 = 7,70·10⁶ Hz/T. Då q/m = 2πs ≈ 4,84·10⁷ C/kg och för q = 2e är m ≈ 6,62·10⁻²⁷ kg.", "(b) Vid B = 0,300 T är f_p = eB/(2πm_p) ≈ 4,57 MHz och f_e = eB/(2πm_e) ≈ 8,40 GHz.", "Grafens alfafrekvens är cirka 2,31 MHz; laddningstecken ändrar rotationsriktningen, inte frekvensbeloppet.", "(c) v = (q/m)Br ≈ 1,74·10⁶ m/s. K = mv²/2 ≈ 1,00·10⁻¹⁴ J ≈ 62,7 keV."], ["(a) In the nonrelativistic model f = (q/m)B/(2π).", "The graph’s approximate slope is (3.08×10⁶)/0.400 = 7.70×10⁶ Hz/T. Thus q/m = 2πs ≈ 4.84×10⁷ C/kg and with q = 2e, m ≈ 6.62×10⁻²⁷ kg.", "(b) At B = 0.300 T, f_p = eB/(2πm_p) ≈ 4.57 MHz and f_e = eB/(2πm_e) ≈ 8.40 GHz.", "The graph’s alpha frequency is about 2.31 MHz; charge sign changes rotation direction, not frequency magnitude.", "(c) v = (q/m)Br ≈ 1.74×10⁶ m/s. K = mv²/2 ≈ 1.00×10⁻¹⁴ J ≈ 62.7 keV."]], "27.80": [["Fältet mot jordens centrum pekar lokalt lodrätt nedåt. Vid 80° nordlig latitud ligger begynnelsehastigheten 10° under lokalhorisonten; dela upp den relativt fältet.", "(a) v_⊥ = v cos10° och r = m_ev_⊥/(eB) = 0,149 m. (b) Fältparallell fart mot ytan är v_∥ = v sin10° = 69,5 km/s; i den lokalt homogena fältmodellen är denna lodräta hastighetskomponent konstant.", "(c) Sedd ovanifrån böjer ett inåtriktat fält en elektron medurs. (d) f = eB/(2πm_e) = 4,20·10⁵ Hz.", "(e) Förflyttning söderut ger elektriskt arbete eEd eftersom elektronen är negativ. I ickerelativistisk energi blir v_f = √[v²+2eEd/m_e] ≈ 2,65·10⁷ m/s.", "(f) K_f/K_i = v_f²/v² ≈ 4,40·10³ inom samma approximation."], ["The field toward Earth’s center is locally vertically downward. At latitude 80° N the initial velocity is 10° below the local horizontal; resolve it relative to the field.", "(a) v_⊥ = v cos10° and r = m_ev_⊥/(eB) = 0.149 m. (b) Field-parallel speed toward the surface is v_∥ = v sin10° = 69.5 km/s; in the locally uniform-field model this vertical velocity component is constant.", "(c) Viewed from above, an inward field curves an electron clockwise. (d) f = eB/(2πm_e) = 4.20×10⁵ Hz.", "(e) Southward displacement gives electric work eEd because the electron is negative. Nonrelativistic energy gives v_f = √[v²+2eEd/m_e] ≈ 2.65×10⁷ m/s.", "(f) K_f/K_i = v_f²/v² ≈ 4.40×10³ within the same approximation."]], "27.81": [["(a) Magnetisk cirkelrörelse ger R = mv/(qB) ≈ 5,14 m. Fältets bredd längs ursprungsriktningen är d = 0,250 m, så sinθ = d/R och θ ≈ 0,0487 rad.", "(b) Vinkelfrekvensen är qB/m och tiden i fältet t₁ = mθ/(qB) ≈ 1,72 μs.", "(c) Sidoförskjutningen vid utgången är Δx₁ = R(1−cosθ) ≈ 6,09 mm.", "(d) I det fältfria området går partikeln rakt ytterligare 0,500 m längs ursprungsriktningen.", "Den extra sidoförskjutningen är 0,500 tanθ, vilket ger totalt cirka 3,04 cm åt vänster."], ["(a) Magnetic circular motion gives R = mv/(qB) ≈ 5.14 m. Field width along the original direction is d = 0.250 m, so sinθ = d/R and θ ≈ 0.0487 rad.", "(b) Angular frequency is qB/m and time in the field t₁ = mθ/(qB) ≈ 1.72 μs.", "(c) Sideways displacement at exit is Δx₁ = R(1−cosθ) ≈ 6.09 mm.", "(d) In the field-free region the particle travels straight a further 0.500 m along the original direction.", "Extra sideways displacement is 0.500 tanθ, giving a total of about 3.04 cm leftward."]], "27.82": [["(a) Den elektriska kraften accelererar först laddningen uppåt; magnetkraften böjer den åt sidan.", "Hastigheten återgår till noll efter en cykel medan banan har förskjutits, så cykloiden upprepas.", "(b) Magnetkraften utför inget arbete. Energibevarande från vila ger mv²/2 = qEy och v = √(2qEy/m).", "(c) Vid toppen är inåtkraften qvB−qE och den givna krökningsradien 2y. Newtons lag ger qvB−qE = mv²/(2y).", "Ur (b) är mv²/(2y) = qE. Då vB−E = E och toppfarten är v = 2E/B."], ["(a) Electric force initially accelerates the charge upward; magnetic force bends it sideways.", "Velocity returns to zero after a cycle while the path has shifted, so the cycloid repeats.", "(b) Magnetic force does no work. Energy conservation from rest gives mv²/2 = qEy and v = √(2qEy/m).", "(c) At the top the inward force is qvB−qE and the stated curvature radius is 2y. Newton’s law gives qvB−qE = mv²/(2y).", "From (b), mv²/(2y) = qE. Thus vB−E = E and top speed is v = 2E/B."]], "27.83": [["Vridmomentets belopp är τ = μB sinθ.", "Momentet och fältet är vinkelräta, så θ = 90° och sinθ = 1.", "Sätt in μ = 1,4·10⁻²⁶ J/T och B = 2 T.", "Då τ = 2,8·10⁻²⁶ N·m.", "Det motsvarar alternativ (c)."], ["Torque magnitude is τ = μB sinθ.", "Moment and field are perpendicular, so θ = 90° and sinθ = 1.", "Insert μ = 1.4×10⁻²⁶ J/T and B = 2 T.", "Then τ = 2.8×10⁻²⁶ N·m.", "This corresponds to choice (c)."]], "27.84": [["I textens modell tar parade protoners och neutroners bidrag ut varandra.", "¹²C har jämnt antal protoner och neutroner.", "¹⁶O och ⁴⁰Ca har också jämnt antal av båda.", "³¹P har 15 protoner och 16 neutroner och kan ha ett magnetiskt nettomoment.", "Det är alternativ (d)."], ["In the passage model paired proton and neutron contributions cancel.", "¹²C has even numbers of protons and neutrons.", "¹⁶O and ⁴⁰Ca also have even numbers of both.", "³¹P has 15 protons and 16 neutrons and can have a net magnetic moment.", "It is choice (d)."]], "27.85": [["Tvärsnittsarean är A = π(0,00075 m)² ≈ 1,77·10⁻⁶ m².", "Med jämn längsgående ström är R = ρL/A = (0,6)(0,0010)/A ≈ 340 Ω.", "Strömmen är I = V/R = 0,100/340 ≈ 2,95·10⁻⁴ A.", "Största kraften fås när ström och fält är vinkelräta: F_max = ILB ≈ 5,9·10⁻⁷ N.", "Närmast är alternativ (a), 6·10⁻⁷ N."], ["Cross-sectional area is A = π(0.00075 m)² ≈ 1.77×10⁻⁶ m².", "With uniform longitudinal current R = ρL/A = (0.6)(0.0010)/A ≈ 340 Ω.", "Current is I = V/R = 0.100/340 ≈ 2.95×10⁻⁴ A.", "Maximum force occurs when current and field are perpendicular: F_max = ILB ≈ 5.9×10⁻⁷ N.", "The closest is choice (a), 6×10⁻⁷ N."]]};for(const e of root.EmberChapter27DraftExercises){const v=reviewed[e.id];if(v){e.sv.steps=v[0];e.en.steps=v[1]}}})(window);
